/// An extra margin added around the [`EnlargedAabb`]. This allows proxies
/// to move a small amount without triggering a tree update.
///
/// This is implicitly scaled by the [`PhysicsLengthUnit`].
// TODO: This should probably be configurable.
const AABB_MARGIN: Scalar = 0.05;

// Initialize `ColliderAabb` for colliders.
app.add_observer(
    |trigger: On<Add, C>,
     mut query: Query<(
        &C,
        &Position,
        &Rotation,
        Option<&CollisionMargin>,
        &mut ColliderAabb,
        &mut EnlargedAabb,
    )>,
     narrow_phase_config: Res<NarrowPhaseConfig>,
     length_unit: Res<PhysicsLengthUnit>,
     collider_context: StaticSystemParam<C::Context>| {
        let contact_tolerance = length_unit.0 * narrow_phase_config.contact_tolerance;
        let margin = length_unit.0 * AABB_MARGIN;

        if let Ok((collider, pos, rot, collision_margin, mut aabb, mut enlarged_aabb)) =
            query.get_mut(trigger.entity)
        {
            let collision_margin = collision_margin.map_or(0.0, |m| m.0);

            // TODO: Should we instead do this in `add_to_tree_on`?
            // Update tight-fitting AABB.
            let context = AabbContext::new(trigger.entity, &*collider_context);
            let growth = Vector::splat(contact_tolerance + collision_margin);
            *aabb = collider
                .aabb_with_context(pos.0, *rot, context)
                .grow(growth);

            enlarged_aabb.update(&aabb, margin);
        }

    && !collider.last_changed().is_newer_than(last_tick.0, this_run)
{
    return;
}

let collision_margin = collision_margin.map_or(0.0, |margin| margin.0);

// Update tight-fitting AABB.
let context = AabbContext::new(entity, &*collider_context);
let growth = Vector::splat(contact_tolerance + collision_margin);
*aabb = collider
    .aabb_with_context(pos.0, *rot, context)
    .grow(growth);

// Try to update the enlarged AABB, and if it changed, mark the proxy as moved.
let moved = enlarged_aabb.update(&aabb, margin);

if moved {
    let tree_type = proxy_key.tree_type();

//       May not be worth it though?
let pairs = moved_proxies.proxies().par_splat_map(
    ComputeTaskPool::get(),
    None,
    |_chunk_index, proxies| {
        let mut pairs = Vec::new();

        par_commands.command_scope(|mut commands| {
            for proxy_key1 in proxies {
                let proxy_id1 = proxy_key1.id();
                let proxy_type1 = proxy_key1.tree_type();

                // Get the proxy from its appropriate tree.
                let tree = trees.tree_for_type(proxy_type1);
                let proxy1 = tree.get_proxy(proxy_key1.id()).unwrap();

                let Some(proxy_aabb1) = tree.get_proxy_aabb(proxy_id1) else {
                    continue;
                };

                // Query dynamic tree.
                query_tree(
                    &trees.dynamic_tree,
                    ColliderTreeType::Dynamic,

        point.penetration += collision_margin_sum;

        // Compute the relative velocity along the contact normal.
        #[cfg(feature = "2d")]
        let relative_velocity = relative_linear_velocity
            + ang_vel2 * point.anchor2.perp()
            - ang_vel1 * point.anchor1.perp();
        #[cfg(feature = "3d")]
        let relative_velocity = relative_linear_velocity
            + ang_vel2.cross(point.anchor2)
            - ang_vel1.cross(point.anchor1);
        let normal_speed = relative_velocity.dot(normal);
        point.normal_speed = normal_speed;

        // Keep the contact if (1) the separation distance is below the required threshold,
        // or if (2) the bodies are expected to come into contact within the next time step.
        -point.penetration < effective_speculative_margin || {
            let delta_distance = normal_speed * delta_secs;
            delta_distance - point.penetration < effective_speculative_margin
        }
    });

    // Prune extra contact points.
    #[cfg(feature = "3d")]
    if manifold.points.len() > 4 {
        manifold.prune_points();
    }

    !manifold.points.is_empty()
});

// Check if the colliders are now touching.
let mut touching = !contacts.manifolds.is_empty();

if touching && contacts.flags.contains(ContactPairFlags::MODIFY_CONTACTS) {
    par_commands.command_scope(|mut commands| {
        touching = hooks.modify_contacts(contacts, &mut commands);
    });
    if !touching {
        contacts.manifolds.clear();
    }
}

contacts.flags.set(ContactPairFlags::TOUCHING, touching);
